import SwiftUI

/// Small monochrome marks for what a container runs, on a 15-point grid. Most
/// come from the Paper icon set; Redis, nginx, RabbitMQ, Elastic, MinIO and
/// Kafka are from Simple Icons (CC0), since the set has no marks for them.
struct ServiceGlyph: View {
    let service: ContainerService?
    var color: Color = Theme.text2

    var body: some View {
        Group {
            if let service {
                ServiceShape(path: Self.path(for: service), size: 15)
                    .fill(color, style: FillStyle(eoFill: service.iconIsEvenOdd))
            } else {
                ContainerGlyph(size: 12, color: color)
            }
        }
        .frame(width: 15, height: 14)
    }

    private static func path(for service: ContainerService) -> Path { Path(iconData: service.iconData) }
}

private struct ServiceShape: Shape {
    let path: Path
    let size: CGFloat

    func path(in rect: CGRect) -> Path {
        path.applying(CGAffineTransform(translationX: rect.midX - size / 2, y: rect.midY - size / 2))
    }
}

extension Path {
    /// Reads the icons below: absolute `M`, `L`, `C` and `Z` commands only.
    init(iconData: String) {
        self.init()
        let tokens = iconData.split(separator: " ")
        var index = 0
        func point() -> CGPoint {
            defer { index += 2 }
            return CGPoint(x: Double(tokens[index]) ?? 0, y: Double(tokens[index + 1]) ?? 0)
        }
        while index < tokens.count {
            let command = tokens[index]
            index += 1
            switch command {
            case "M": move(to: point())
            case "L": addLine(to: point())
            case "C":
                let first = point(), second = point()
                addCurve(to: point(), control1: first, control2: second)
            default: closeSubpath()
            }
        }
    }
}

